<?php
declare(strict_types=1);namespace App\Core;use PDO;use Throwable;
final class Database{private static ?PDO $pdo=null;public static function pdo():PDO{if(self::$pdo)return self::$pdo;$dsn='mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset='.DB_CHARSET;self::$pdo=new PDO($dsn,DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);self::$pdo->exec("SET time_zone='-06:00'");return self::$pdo;}public static function transaction(callable $cb):mixed{$pdo=self::pdo();$pdo->beginTransaction();try{$r=$cb($pdo);$pdo->commit();return $r;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}}
